import StorageCore
import SwiftUI

/// The hand-inked illustrations, generated by `ios/Tools/illustrations/generate.py`.
/// The app draws them from `IllustrationArt.swift` (also generated) rather
/// than the asset catalog, so they show in every build, including xtool's.
/// Colors come from `Theme`, so dark mode switches automatically.
enum Illustration: String, CaseIterable {
    case beaker = "ill-beaker"
    case compress = "ill-compress"
    case emptyBox = "ill-empty-box"
    case lock = "ill-lock"
    case phoneSparkle = "ill-phone-sparkle"
    case photo = "ill-photo"
    case piggy = "ill-piggy"
    case reset = "ill-reset"
    case screenshot = "ill-screenshot"
    case shieldCheck = "ill-shield-check"
    case stackLarge = "ill-stack-large"
    case stackSmall = "ill-stack-small"
    case trash = "ill-trash"
    case umbrella = "ill-umbrella"
    case video = "ill-video"

    static func forCategory(_ category: MediaCategory) -> Illustration {
        switch category {
        case .photo: .photo
        case .video: .video
        case .screenshot: .screenshot
        }
    }

    static func forGroup(_ group: ScanGroup) -> Illustration {
        switch group {
        case .photos, .livePhotos: .photo
        case .bursts: .stackSmall
        case .screenshots: .screenshot
        case .videos: .video
        case .bigFormats: .stackLarge
        }
    }
}

/// Shows an illustration at a fixed size. Decorative by default, so VoiceOver skips it.
struct IllustrationView: View {
    let illustration: Illustration
    var size: CGFloat = 56

    init(_ illustration: Illustration, size: CGFloat = 56) {
        self.illustration = illustration
        self.size = size
    }

    var body: some View {
        let layers = IllustrationLayer.parsed(illustration.rawValue)
        Canvas { context, canvasSize in
            let scale = min(canvasSize.width, canvasSize.height) / IllustrationLayer.canvas
            context.scaleBy(x: scale, y: scale)
            for layer in layers {
                switch layer.kind {
                case .fill:
                    context.fill(layer.path, with: .color(layer.role.color))
                case .stroke(let width):
                    context.stroke(layer.path, with: .color(layer.role.color),
                                   style: StrokeStyle(lineWidth: width, lineCap: .round, lineJoin: .round))
                }
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}

/// One layer of an illustration, in the generator's 96-point canvas.
enum IllustrationLayer {
    enum Role {
        case ink, mint, paper, shade

        var color: Color {
            switch self {
            case .ink: Theme.ink
            case .mint: Theme.mint
            case .paper: Theme.illustrationPaper
            case .shade: Theme.illustrationShade
            }
        }
    }

    case fill(Role, String)
    case stroke(Role, CGFloat, String)
    case dot(Role, CGFloat, CGFloat, CGFloat)

    static let canvas: CGFloat = 96

    struct Drawn {
        enum Kind { case fill, stroke(CGFloat) }
        let kind: Kind
        let role: Role
        let path: Path
    }

    /// Parsed once per illustration, then reused.
    @MainActor private static var cache: [String: [Drawn]] = [:]

    @MainActor
    static func parsed(_ name: String) -> [Drawn] {
        if let cached = cache[name] { return cached }
        let drawn = layers(for: name).map { layer -> Drawn in
            switch layer {
            case .fill(let role, let d): Drawn(kind: .fill, role: role, path: SVGPath.parse(d))
            case .stroke(let role, let width, let d): Drawn(kind: .stroke(width), role: role, path: SVGPath.parse(d))
            case .dot(let role, let x, let y, let r):
                Drawn(kind: .fill, role: role, path: Path(ellipseIn: CGRect(x: x - r, y: y - r, width: r * 2, height: r * 2)))
            }
        }
        cache[name] = drawn
        return drawn
    }
}

/// Reads the absolute SVG path commands the generator writes: M, L, Q, C and Z.
enum SVGPath {
    static func parse(_ d: String) -> Path {
        var path = Path()
        var numbers: [CGFloat] = []
        var command: Character = "M"
        var token = ""

        func flushToken() {
            if let value = Double(token) { numbers.append(CGFloat(value)) }
            token = ""
        }
        func apply() {
            var i = 0
            func point() -> CGPoint {
                defer { i += 2 }
                return CGPoint(x: numbers[i], y: numbers[i + 1])
            }
            switch command {
            case "M":
                while i + 1 < numbers.count {
                    let p = point()
                    if i == 2 { path.move(to: p) } else { path.addLine(to: p) }
                }
            case "L":
                while i + 1 < numbers.count { path.addLine(to: point()) }
            case "Q":
                while i + 3 < numbers.count {
                    let control = point()
                    path.addQuadCurve(to: point(), control: control)
                }
            case "C":
                while i + 5 < numbers.count {
                    let c1 = point(), c2 = point()
                    path.addCurve(to: point(), control1: c1, control2: c2)
                }
            case "Z":
                path.closeSubpath()
            default:
                break
            }
            numbers.removeAll(keepingCapacity: true)
        }

        for character in d {
            if character.isLetter {
                flushToken()
                apply()
                command = character
            } else if character == "," || character == " " {
                flushToken()
            } else if character == "-", !token.isEmpty, token.last != "e" {
                flushToken()
                token = "-"
            } else {
                token.append(character)
            }
        }
        flushToken()
        apply()
        return path
    }
}

/// A hand-drawn wavy underline, used under the headline savings figure.
struct Squiggle: Shape {
    var waves: Int = 7

    func path(in rect: CGRect) -> Path {
        var path = Path()
        let step = rect.width / CGFloat(waves * 2)
        path.move(to: CGPoint(x: rect.minX, y: rect.midY))
        for i in 0..<(waves * 2) {
            let x = rect.minX + step * CGFloat(i + 1)
            let control = CGPoint(x: x - step / 2, y: i.isMultiple(of: 2) ? rect.minY : rect.maxY)
            path.addQuadCurve(to: CGPoint(x: x, y: rect.midY), control: control)
        }
        return path
    }
}

#Preview("Illustrations") {
    ScrollView {
        LazyVGrid(columns: [GridItem(.adaptive(minimum: 80))], spacing: 20) {
            ForEach(Illustration.allCases, id: \.self) { item in
                VStack {
                    IllustrationView(item, size: 64)
                    Text(item.rawValue).font(.caption2).foregroundStyle(.secondary)
                }
            }
        }
        .padding()
        Squiggle().stroke(Theme.mint, style: StrokeStyle(lineWidth: 3, lineCap: .round)).frame(width: 160, height: 8)
    }
    .background(Theme.background)
}
